def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    coords = {1, n + 1}
    for op in ops:
        coords.add(op[1])
        coords.add(op[2] + 1)
    xs = sorted(coords)
    pos = {x: i for i, x in enumerate(xs)}
    m = len(xs) - 1

    # Tag kinds: 0 -> x becomes max(x, v); 1 -> x becomes v (constant)
    K = [0] * (4 * m)
    V = [0] * (4 * m)

    def combine(nk, nv, ok, ov):
        # Tag equivalent to applying old tag (ok, ov) first, then new tag (nk, nv)
        if nk == 1:
            return 1, nv
        if ok == 1:
            return 1, max(ov, nv)
        return 0, max(ov, nv)

    def push(node):
        k, v = K[node], V[node]
        if k == 0 and v == 0:
            return
        for child in (2 * node, 2 * node + 1):
            K[child], V[child] = combine(k, v, K[child], V[child])
        K[node] = 0
        V[node] = 0

    def update(node, lo, hi, a, b, k, v):
        if b <= lo or hi <= a:
            return
        if a <= lo and hi <= b:
            K[node], V[node] = combine(k, v, K[node], V[node])
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, a, b, k, v)
        update(2 * node + 1, mid, hi, a, b, k, v)

    for op in ops:
        a = pos[op[1]]
        b = pos[op[2] + 1]
        if op[0] == 1:
            update(1, 0, m, a, b, 0, op[3])
        else:
            update(1, 0, m, a, b, 1, 0)

    totals = {}

    def collect(node, lo, hi):
        if hi - lo == 1:
            c = V[node]
            if c:
                totals[c] = totals.get(c, 0) + xs[hi] - xs[lo]
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid)
        collect(2 * node + 1, mid, hi)

    collect(1, 0, m)
    return [[c, totals[c]] for c in sorted(totals)]
